# -*- coding: utf-8 -*-
"""ELIOT R35.4: secure mirror failover and local offline wheelhouse for R35.3.

One-shot auxiliary launcher; uses the existing, SHA-attested R35.1 one-file updater.
Does not rewrite updater, game, old WAVs, model weights, or protected voices.
Only previously reviewed R35.3 may modify the private stress-validation venv,
after all wheels have downloaded with TLS verification and ZIP CRC validation.
"""
from __future__ import annotations
import base64, gzip, hashlib, importlib.util, json, os, pathlib, subprocess, sys, tempfile, zipfile

PRIOR_R353_SHA = '1638e052d2166c09dfc842b9fdeead864d8c2096fa0a11c2a2beba95c10a8c86'
PRIOR_R353_GZIP_B64 = ''
PINS = ('transformers==4.57.3','tokenizers==0.22.1','huggingface-hub==0.36.0')
INDEXES = (
    ('official-pypi','https://pypi.org/simple/'),
    ('yandex-mirror','https://mirror.yandex.ru/mirrors/pypi/simple/'),
    ('tsinghua-mirror','https://pypi.tuna.tsinghua.edu.cn/simple/'),
    ('aliyun-mirror','https://mirrors.aliyun.com/pypi/simple/'),
)

def sha(b): return hashlib.sha256(b).hexdigest()

def old_script():
    b=gzip.decompress(base64.b64decode(PRIOR_R353_GZIP_B64,validate=True))
    if sha(b)!=PRIOR_R353_SHA: raise RuntimeError('R353_EMBEDDED_SHA_HOLD')
    return b

def verify_updater(cmd):
    ns={'__name__':'eliot_r353_attest_only','__file__':'<attested>'}
    exec(compile(old_script().decode('utf-8'),'R35_3.py','exec'),ns)
    return ns['attest_updater'](cmd)

def wheelhouse_complete(python,wheelhouse):
    # Real pip resolver with network explicitly disabled. Includes transitives.
    cmd=[str(python),'-m','pip','download','--disable-pip-version-check',
        '--no-index','--find-links',str(wheelhouse),'--only-binary=:all:',
        '--dest',str(wheelhouse),'--no-input','--quiet',*PINS]
    env=os.environ.copy()
    env.update(PIP_NO_INDEX='1',PIP_FIND_LINKS=str(wheelhouse),PIP_DISABLE_PIP_VERSION_CHECK='1')
    try:
        r=subprocess.run(cmd,env=env,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,timeout=90)
        return r.returncode==0
    except (OSError,subprocess.TimeoutExpired): return False

def scan_wheels(wheelhouse):
    wheels=list(wheelhouse.glob('*.whl'))
    if not wheels: raise RuntimeError('NO_WHEELS_DOWNLOADED')
    if len(wheels)>200: raise RuntimeError('SUSPICIOUS_WHEEL_COUNT_HOLD')
    for w in wheels:
        if w.is_symlink() or w.stat().st_size<500: raise RuntimeError('BAD_WHEEL_HOLD '+w.name)
        with zipfile.ZipFile(w) as z:
            if not any(x.endswith('.dist-info/WHEEL') for x in z.namelist()):raise RuntimeError('NOT_A_WHEEL '+w.name)
            bad=z.testzip()
            if bad: raise RuntimeError('WHEEL_CRC_HOLD '+w.name+' '+bad)
    return len(wheels)

def env_for_download(index):
    env=os.environ.copy()
    # Prevent stale site-specific pip config or insecure host overrides.
    env.pop('PIP_NO_INDEX',None)
    env.pop('PIP_FIND_LINKS',None)
    env.pop('PIP_EXTRA_INDEX_URL',None)
    env.pop('PIP_TRUSTED_HOST',None)
    env['PIP_CONFIG_FILE']=os.devnull
    env['PIP_INDEX_URL']=index
    env['PIP_DISABLE_PIP_VERSION_CHECK']='1'
    return env

def download_wheels(python,wheelhouse):
    for name,index in INDEXES:
        print('ELIOT_R35_4_TRY_SECURE_INDEX',name,flush=True)
        cmd=[str(python),'-m','pip','download',
             '--index-url',index,'--only-binary=:all:','--dest',str(wheelhouse),
             '--disable-pip-version-check','--no-input', '--retries','1','--timeout','18',*PINS]
        try:
            p=subprocess.run(cmd,env=env_for_download(index),timeout=240)
        except (OSError,subprocess.TimeoutExpired) as exc:
            print('ELIOT_R35_4_INDEX_TIMEOUT_OR_ERROR',name,type(exc).__name__,flush=True)
            continue
        if p.returncode==0 and wheelhouse_complete(python,wheelhouse):
            n=scan_wheels(wheelhouse)
            print('ELIOT_R35_4_OFFLINE_WHEELHOUSE_READY',n,'source',name,flush=True)
            return name
        print('ELIOT_R35_4_INDEX_UNAVAILABLE',name,'rc',p.returncode,flush=True)
    raise RuntimeError('ALL_TLS_INDEXES_UNAVAILABLE_HOLD__NO_VENV_CHANGES')

def selftest():
    raw=old_script(); assert sha(raw)==PRIOR_R353_SHA
    assert len(set(PINS))==3
    assert all(i.startswith('https://') for _,i in INDEXES)
    assert 'PIP_TRUSTED_HOST' not in env_for_download(INDEXES[0][1])
    assert len(INDEXES)>=2
    print('ELIOT_R35_4_SELFTEST_PASS previous R35.3 exact; TLS mirror URLs; offline wheelhouse gate',flush=True)

def main():
    selftest()
    if '--selftest-only' in sys.argv: return 0
    if os.name!='nt' or sys.version_info[:2]!=(3,11):raise RuntimeError('WINDOWS_PYTHON_3_11_REQUIRED')
    home=pathlib.Path.home()
    root=home/'Documents'/'BG_VOICE_RU'/'FULL_PRODUCTION'
    cmd=home/'Downloads'/'BG_VOICE_RU_TTS_READY'/'bg_voice_release_v2'/'BG_VOICE_UPDATE.cmd'
    current=verify_updater(cmd)
    venv=root/'ELIOT_R35_TEXT_ONLY_VENV'/'Scripts'/'python.exe'
    if not venv.is_file() or venv.is_symlink():raise RuntimeError('TEXT_ONLY_VENV_NOT_FOUND')
    wheelhouse=root/'ELIOT_R35_3_WHEEL_CACHE'
    if wheelhouse.is_symlink():raise RuntimeError('WHEELHOUSE_SYMLINK_HOLD')
    wheelhouse.mkdir(parents=True,exist_ok=True)
    if wheelhouse_complete(venv,wheelhouse):
        n=scan_wheels(wheelhouse)
        print('ELIOT_R35_4_WHEELHOUSE_REUSED',n,flush=True)
    else:
        download_wheels(venv,wheelhouse)
    # Recheck updater just before handoff; the prior R35.3 enforces the same SHA.
    if sha(cmd.read_bytes())!=current:raise RuntimeError('UPDATER_CHANGED_HOLD')
    env=os.environ.copy()
    env['PIP_NO_INDEX']='1'
    env['PIP_FIND_LINKS']=str(wheelhouse)
    env['PIP_DISABLE_PIP_VERSION_CHECK']='1'
    env.pop('PIP_INDEX_URL',None)
    env.pop('PIP_EXTRA_INDEX_URL',None)
    env.pop('PIP_TRUSTED_HOST',None)
    prior=old_script()
    fd,temp=tempfile.mkstemp(prefix='ELIOT_R35_3_VERIFIED_',suffix='.py')
    try:
        with os.fdopen(fd,'wb') as f:
            f.write(prior); f.flush();os.fsync(f.fileno())
        print('ELIOT_R35_4_HANDOFF_VERIFIED_R35_3_OFFLINE',flush=True)
        rc=subprocess.call([sys.executable,'-u',temp],env=env)
        if rc:raise RuntimeError('R35_3_HOLD_RC_'+str(rc)+'_NO_UNVERIFIED_SYNTHESIS')
    finally:
        pathlib.Path(temp).unlink(missing_ok=True)
    print('ELIOT_R35_4_SUCCESS: R35.3 checks and controlled movie pilots complete',flush=True)
    return 0

if __name__=='__main__':
    try:raise SystemExit(main())
    except Exception as e:
        print('ELIOT_R35_4_HOLD',type(e).__name__,str(e)[:480],flush=True)
        raise SystemExit(2)
